export type ParsedClaimInstruction<
  TProgram extends string = typeof EASYPAY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /**
     * Who sends the claim: the worker, or the auto-claim key the worker put in `split.claimer`. The handler
     * checks. Pays the fee.
     */
    signer: TAccountMetas[0];
    /** The worker of the slot. The handler checks the slot holds this key. Not a signer: auto-claim claims for them. */
    employee: TAccountMetas[1];
    /**
     * Any pool. Account<Pool> already checks our program owns it and that it is a Pool,
     * and only create_pool makes those, always at the employer's PDA.
     */
    pool: TAccountMetas[2];
    /** The pool's vault. The money comes from here. */
    vault: TAccountMetas[3];
    /** The worker's own USDC account. The app creates it in the same transaction if it is missing. */
    employeeUsdc: TAccountMetas[4];
    /**
     * The worker's Split PDA, read by the handler. Unchecked because it may not exist: a worker who never
     * saved a split gets everything, as before splits existed.
     */
    split: TAccountMetas[5];
    exchange: TAccountMetas[6];
    exchangeUsdc: TAccountMetas[7];
    price: TAccountMetas[8];
    assetMint?: TAccountMetas[9] | undefined;
    /** for the asset mint, which the app creates in the same transaction. The handler checks both. */
    employeeAsset: TAccountMetas[10];
    mint: TAccountMetas[11];
    tokenProgram: TAccountMetas[12];
  };
  data: ClaimInstructionData;
};

export function parseClaimInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === EASYPAY_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      signer: getNextAccount(),
      employee: getNextAccount(),
      pool: getNextAccount(),
      vault: getNextAccount(),
      employeeUsdc: getNextAccount(),
      split: getNextAccount(),
      exchange: getNextAccount(),
      exchangeUsdc: getNextAccount(),
      price: getNextAccount(),
      assetMint: getNextOptionalAccount(),
      employeeAsset: getNextAccount(),
      mint: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getClaimInstructionDataDecoder().decode(instruction.data),
  };
}
